376			return nil, err
377		}
378		defer countStatement.Close()
379	
380		for _, target := range targets {
381			var count int
382			if err := countStatement.QueryRow(serviceName, target.InstanceID).Scan(&count); err != nil {
383				return nil, err
384			}
385			if count == 0 {
386				return nil, ErrInstanceNotFound
387			}
388		}
389	
390		updateStatement, err := tx.Prepare(`
391	UPDATE service_instances SET weight = ?
392	WHERE service_name = ? AND instance_id = ?`)
393		if err != nil {
394			return nil, err
395		}
396		defer updateStatement.Close()
397	
398		for _, target := range targets {
399			if _, err := updateStatement.Exec(target.Weight, serviceName, target.InstanceID); err != nil {
400				return nil, err
401			}
402		}
403	
404		updated := make([]Instance, 0, len(targets))
405		for _, target := range targets {
406			row := tx.QueryRow(`
407	SELECT service_name, instance_id, address, port, healthy, weight, heartbeat_at
408	FROM service_instances
409	WHERE service_name = ? AND instance_id = ?`, serviceName, target.InstanceID)
410			instance, err := scanInstance(row)
411			if err == sql.ErrNoRows {
412				return nil, ErrInstanceNotFound
413			}
414			if err != nil {
415				return nil, err
416			}
417			updated = append(updated, instance)
418		}
419	
420		if err := tx.Commit(); err != nil {
421			return nil, err
422		}
423		return updated, nil
