13	// This file pins the published batch-registration contract: when the storage
14	// layer fails in the middle of a batch — earlier entries already written,
15	// later ones not yet reached — the whole batch rolls back, both batch
16	// entries answer HTTP 503 with only the top-level storage_unavailable error
17	// object, and the identical request succeeds once the fault clears. Every
18	// check runs against a real SQLite file and is repeated after closing and
19	// reopening the database.
20	
21	// injectBatchWriteFault installs SQLite triggers that abort any insert or
22	// update of the named instance id, so a batch write fails exactly when it
23	// reaches that entry: entries before it are already written inside the batch
24	// transaction, entries after it never run. Both trigger kinds are installed
25	// because an upsert of an existing row and an insert of a new row may take
26	// different trigger paths. The returned function drops the triggers,
27	// modelling the storage fault being cleared.
28	func injectBatchWriteFault(t *testing.T, path, instanceID string) (clear func()) {
29		t.Helper()
30		db, err := sql.Open("sqlite", path)
31		if err != nil {
32			t.Fatalf("open fault injector: %v", err)
33		}
34		t.Cleanup(func() { db.Close() })
35		quoted := "'" + strings.ReplaceAll(instanceID, "'", "''") + "'"
36		for _, kind := range []string{"INSERT", "UPDATE"} {
37			name := "batch_fail_" + strings.ToLower(kind)
38			if _, err := db.Exec(fmt.Sprintf(
39				`CREATE TRIGGER %s BEFORE %s ON service_instances
40				WHEN NEW.instance_id = %s
41				BEGIN SELECT RAISE(ABORT, 'injected batch write failure'); END`,
42				name, kind, quoted)); err != nil {
43				t.Fatalf("inject %s fault: %v", kind, err)
44			}
45		}
46		return func() {
47			for _, kind := range []string{"INSERT", "UPDATE"} {
48				name := "batch_fail_" + strings.ToLower(kind)
49				if _, err := db.Exec("DROP TRIGGER " + name); err != nil {
50					t.Fatalf("clear %s fault: %v", kind, err)
51				}
52			}
53		}
54	}
